//! The synthetic sample set (examples/sample, generated by tests/make_samples.py) through the whole pipeline:
//! the finding codes of every file and every mbox message must be exactly expected_findings.json, every
//! per-message output must be hashed in the audit chain, and dkimpy (tests/oracle_dkim.py, via RV_TEST_PYTHON)
//! must agree with every DKIM verdict.

use rv_mailauth_core::model::DomainOptions;
use rv_mailauth_core::{HashAlgo, RunConfig, run};
use serde_json::Value;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn expected() -> Value {
    serde_json::from_str(
        &std::fs::read_to_string(root().join("examples/sample/expected_findings.json")).unwrap(),
    )
    .unwrap()
}

fn sample_options(exp: &Value) -> DomainOptions {
    DomainOptions {
        dkim_keys: Some(root().join(exp["options"]["dkim_keys"].as_str().unwrap())),
        own_domains: exp["options"]["own_domains"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect(),
        ..DomainOptions::default()
    }
}

fn run_samples(out: &Path, domain: DomainOptions) -> rv_mailauth_core::RunSummary {
    let cfg = RunConfig {
        inputs: vec![root().join("examples/sample/evidence")],
        algorithms: vec![HashAlgo::Sha256, HashAlgo::Md5],
        out_dir: out.to_path_buf(),
        langs: vec!["en".into()],
        actor: "samples-test".into(),
        tsa_url: None,
        domain,
        ..RunConfig::default()
    };
    run(&cfg, &mut |_| {}, &AtomicBool::new(false)).unwrap()
}

/// file name (mbox messages as "<file>#<n>") → sorted finding codes, from the technical.json reports.
fn findings_by_item(report_dir: &Path) -> BTreeMap<String, Vec<String>> {
    let mut got = BTreeMap::new();
    for e in std::fs::read_dir(report_dir.join("items")).unwrap() {
        let dir = e.unwrap().path();
        let t: Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("technical.json")).unwrap())
                .unwrap();
        let name = t["item"]["file_name"].as_str().unwrap();
        let key = match name.rsplit_once('@') {
            Some((k, off)) if k.contains('#') && off.bytes().all(|b| b.is_ascii_digit()) => {
                k.to_string()
            }
            _ => name.to_string(),
        };
        let mut codes: Vec<String> = t["findings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|f| f["code"].as_str().unwrap().to_string())
            .collect();
        codes.sort();
        got.insert(key, codes);
    }
    got
}

/// SHA-256 of `name` in the run's hashes.csv (index,path,size,sha256,md5,status,error).
fn csv_sha256(log_dir: &Path, name: &str) -> String {
    let csv = std::fs::read_to_string(log_dir.join("hashes.csv")).unwrap();
    let line = csv
        .lines()
        .find(|l| l.contains(name) && !l.contains(&format!("{name}#")))
        .unwrap();
    let f: Vec<&str> = line.rsplitn(5, ',').collect();
    f[3].to_string()
}

#[test]
fn samples_give_exactly_the_expected_findings_and_dkimpy_agrees() {
    let exp = expected();
    let out = tempfile::tempdir().unwrap();
    let s = run_samples(out.path(), sample_options(&exp));
    let got = findings_by_item(&s.report_dir);
    let want: BTreeMap<String, Vec<String>> = serde_json::from_value(exp["files"].clone()).unwrap();
    let mut diffs = Vec::new();
    for (k, v) in &want {
        if got.get(k) != Some(v) {
            diffs.push(format!("{k}: expected {v:?}, got {:?}", got.get(k)));
        }
    }
    for k in got.keys().filter(|k| !want.contains_key(*k)) {
        diffs.push(format!(
            "{k}: not in expected_findings.json (got {:?})",
            got[k]
        ));
    }
    assert!(diffs.is_empty(), "\n{}", diffs.join("\n"));
    assert!(
        s.high > 0,
        "the tampered samples have high findings (exit 3)"
    );

    // Every per-message output is in the audit chain with its digest; the mbox expanded into three items.
    let audit = std::fs::read_to_string(s.log_dir.join("audit.jsonl")).unwrap();
    let entries: Vec<Value> = audit
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect();
    let written: Vec<String> = entries
        .iter()
        .filter(|e| e["action"] == "output_written")
        .map(|e| e["details"]["file"].as_str().unwrap().to_string())
        .collect();
    for e in std::fs::read_dir(s.report_dir.join("items")).unwrap() {
        let dir = e.unwrap().path();
        for f in ["headers.json", "dkim.json", "mbox_index.json"] {
            if dir.join(f).is_file() {
                let rel = format!("items/{}/{}", dir.file_name().unwrap().to_string_lossy(), f);
                assert!(written.contains(&rel), "{rel} not audited");
            }
        }
    }
    assert_eq!(
        entries
            .iter()
            .filter(|e| e["action"] == "message_started")
            .count(),
        3
    );
    assert!(entries.iter().any(
        |e| e["action"] == "analysis_configured" && e["details"]["dkim_key_file"]["keys"] == 4
    ));
    // Every mbox message cites its source (mbox digest + index + byte offset) in its technical report and
    // custody form (JSON, HTML and PDF text).
    let mbox_sha = csv_sha256(&s.log_dir, "12-mailbox.mbox");
    let mut cited = 0;
    for e in std::fs::read_dir(s.report_dir.join("items")).unwrap() {
        let dir = e.unwrap().path();
        if !dir.to_string_lossy().contains("12-mailbox.mbox_") {
            continue;
        }
        for f in ["technical.json", "custody.json"] {
            let j: Value =
                serde_json::from_str(&std::fs::read_to_string(dir.join(f)).unwrap()).unwrap();
            assert_eq!(
                j["derived_from"]["container_hashes"]["sha256"],
                mbox_sha.as_str(),
                "{f}"
            );
            assert!(j["derived_from"]["message_offset"].as_u64().unwrap() > 0);
        }
        for f in ["technical.en.html", "custody.en.html", "custody.es.html"] {
            let h = std::fs::read_to_string(dir.join(f)).unwrap();
            assert!(h.contains(&mbox_sha), "{f} does not cite the mbox digest");
        }
        cited += 1;
    }
    assert_eq!(cited, 3);
    // hashes.csv lists the messages (path = <mbox>#<n>@<offset>) after their mbox.
    let csv = std::fs::read_to_string(s.log_dir.join("hashes.csv")).unwrap();
    assert_eq!(csv.lines().filter(|l| l.contains(".mbox#")).count(), 3);

    // Independent oracle: dkimpy over the same evidence and keys.
    let py = std::env::var("RV_TEST_PYTHON").unwrap_or_else(|_| "python3".into());
    let o = std::process::Command::new(&py)
        .arg(root().join("tests/oracle_dkim.py"))
        .arg(root().join("examples/sample/evidence"))
        .arg(root().join("examples/sample/dkim-keys.txt"))
        .arg(&s.report_dir)
        .output();
    match o {
        Err(e) => eprintln!("SKIP dkimpy oracle: cannot run {py}: {e}"),
        Ok(o) if o.status.code() == Some(77) => {
            eprintln!("SKIP dkimpy oracle: {}", String::from_utf8_lossy(&o.stdout))
        }
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            assert!(
                o.status.success(),
                "{}{}",
                text,
                String::from_utf8_lossy(&o.stderr)
            );
            eprintln!("{text}");
            assert!(text.contains("OK: dkimpy agrees"), "{text}");
        }
    }
}

/// Online mode hands the worker keys fetched by the parent (source current_dns): a pass with such a key always
/// carries DKIM_KEY_FROM_CURRENT_DNS. (No network here: the "fetched" key is the sample key re-labelled.)
#[test]
fn keys_from_current_dns_are_flagged() {
    let (keys, _, _) =
        rv_mailauth_core::dkim::load_key_file(&root().join("examples/sample/dkim-keys.txt"))
            .unwrap();
    let fetched: Vec<_> = keys
        .into_iter()
        .map(|mut k| {
            k.source = "current_dns".into();
            k.line = 0;
            k
        })
        .collect();
    let opts = DomainOptions {
        online_dns: true,
        fetched_keys: fetched.clone(),
        ..DomainOptions::default()
    };
    let bytes = std::fs::read(root().join("examples/sample/evidence/01-clean-rsa.eml")).unwrap();
    let o = rv_mailauth_core::mail::analyze_bytes(
        &bytes,
        rv_mailauth_core::model::ItemKind::Eml,
        Default::default(),
        &fetched,
        &opts,
    );
    let mut c: Vec<&str> = o.findings.iter().map(|f| f.code.as_str()).collect();
    c.sort();
    assert_eq!(
        c,
        [
            "AUTH_RESULTS_RECORDED",
            "DKIM_KEY_FROM_CURRENT_DNS",
            "DKIM_SIGNATURE_VALID"
        ]
    );
    assert_eq!(o.analysis.dkim.signatures[0].key_source, "current_dns");
    assert_eq!(o.analysis.dkim.mode, "online");
}

#[test]
fn without_keys_every_signature_is_unchecked_but_body_edits_still_show() {
    let out = tempfile::tempdir().unwrap();
    let s = run_samples(out.path(), DomainOptions::default());
    let got = findings_by_item(&s.report_dir);
    // The body hash is checked before the key is needed: still found with no key at all.
    assert!(got["03-body-edited.eml"].contains(&"DKIM_BODY_HASH_MISMATCH".to_string()));
    assert_eq!(
        got["01-clean-rsa.eml"],
        ["AUTH_RESULTS_RECORDED", "DKIM_KEY_NOT_AVAILABLE"]
    );
    // No own domains configured: no lookalike signal.
    assert_eq!(got["06-lookalike-domain.eml"], ["DKIM_NOT_SIGNED"]);
}

#[test]
fn attachments_are_extracted_only_when_asked_and_are_audited() {
    let exp = expected();
    let out = tempfile::tempdir().unwrap();
    let s = run_samples(
        out.path(),
        DomainOptions {
            extract_attachments: true,
            ..sample_options(&exp)
        },
    );
    let dir = std::fs::read_dir(s.report_dir.join("items"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| p.to_string_lossy().contains("14-not-aligned"))
        .unwrap();
    let att = dir.join("attachments/001-informe.csv");
    assert_eq!(
        std::fs::read(&att).unwrap(),
        b"Fecha;Importe\n2026-11-12;100\n"
    );
    let audit = std::fs::read_to_string(s.log_dir.join("audit.jsonl")).unwrap();
    assert!(audit.contains("attachments/001-informe.csv"));
    let headers: Value =
        serde_json::from_str(&std::fs::read_to_string(dir.join("headers.json")).unwrap()).unwrap();
    assert_eq!(
        headers["attachments"][0]["extracted"],
        "attachments/001-informe.csv"
    );
    let off = tempfile::tempdir().unwrap();
    let s = run_samples(off.path(), sample_options(&exp));
    assert!(
        !std::fs::read_to_string(s.log_dir.join("audit.jsonl"))
            .unwrap()
            .contains("\"kind\":\"attachment\"")
    );
}
